  let tmp = mod_(1u64, m);
  let tmp_1 = egcd_loop_1(m, n, m, tmp, 0u64);
  match tmp_1 {
    (v27, v29) => {
      let mg = div(m, v27);
      let tmp_2 = add(b, m);
      let tmp_3 = mod_(a, m);
      let d = mod_(sub(tmp_2, tmp_3), m);
      let tmp_4 = mod_(d, v27);
      if eqb(tmp_4, 0u64) {
        let t = mod_(mul(div(d, v27), v29), mg);
        Rc::new(option::<(u64, u64)>::Some((add(a, mul(n, t)), mul(n, mg))))
      } else {
        Rc::new(option::<(u64, u64)>::None)
      }
    },
  }
}
